$fields=['Date'=>transaction_date($h['entry_date']),$summary['type']==='Payment'?'Payee':($summary['type']==='Receipt'?'Source / Payer':'Party')=>$summary['party'],'Reference'=>$summary['reference'],'Project'=>$summary['project'],'Book'=>$bookLabel,'Recorded by'=>$summary['recorded_by'],'Recorded at'=>transaction_time($summary['recorded_at'],($h['recorded_timezone']??'')==='UTC')];
layout_begin($heading,$ledgerBack!==null?'general_ledger':(['CDB'=>'cdb','CRB'=>'crb'][$book]??'financial_records'),[], '<link rel="stylesheet" href="assets/css/transaction_workspace.css?v='.filemtime(__DIR__.'/../assets/css/transaction_workspace.css').'">');
