<?php ui_page_heading($heading,'','<a class="ui-button" href="'.ui_escape($back).'">'.ui_escape($backLabel).'</a>'); ?>
<section class="tx-card"><div class="tx-toolbar"><span class="tx-chip"><?= ui_escape($summary['status']) ?></span><button type="button" class="ui-button tx-print-control" onclick="window.print()">Print transaction</button></div>
<?php if($summary['amount']!==null):?><p class="tx-main-amount"><?= ui_escape($summary['amount_text']) ?></p><?php else:?><p class="tx-amount-note"><?= ui_escape($summary['amount_text']) ?></p><?php endif;?>
<h2 class="tx-purpose"><?= ui_escape($h['description']) ?></h2>
<dl class="tx-summary"><?php foreach($fields as $label=>$value):?><div><dt><?= ui_escape($label) ?></dt><dd><?= ui_escape($value) ?></dd></div><?php endforeach;?></dl>
<?php if($summary['cash_account']!==''):?><section><h3><?= $book==='CDB'?'Paid from':'Received into' ?></h3><p><?= ui_escape($summary['cash_account']) ?></p><h3>Recorded against</h3><?php foreach($summary['allocations'] as $l):?><p><?= ui_escape($l['account_name']) ?> · <?= ui_escape(transaction_project_label($l)) ?> · <?= ui_escape(accounting_cents($l['debit_amount'])>0?'Debit '.accounting_money($l['debit_amount']):'Credit '.accounting_money($l['credit_amount'])) ?></p><?php endforeach;?></section><?php endif;?>
<details class="tx-accounting"><summary>Accounting details</summary><div class="tx-table-region" role="region" aria-label="Complete debit and credit posting" tabindex="0"><table class="tx-table tx-journal-table"><caption class="tx-sr-only">Complete journal, including every counterpart line</caption><thead><tr><th scope="col">Account (current name)</th><th scope="col">Project at recording</th><th scope="col">Debit (PHP)</th><th scope="col">Credit (PHP)</th></tr></thead><tbody><?php foreach($j['lines'] as $l):?><tr><td><?= ui_escape($l['account_name'].' · '.($l['account_code']?:'#'.$l['account_id'])) ?></td><td><?= ui_escape(transaction_project_label($l)) ?></td><td><?= ui_escape(accounting_money($l['debit_amount'])) ?></td><td><?= ui_escape(accounting_money($l['credit_amount'])) ?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="2">Complete entry totals</th><td><?= ui_escape(accounting_money(accounting_decimal((int)$j['debit_cents']))) ?></td><td><?= ui_escape(accounting_money(accounting_decimal((int)$j['credit_cents']))) ?></td></tr></tfoot></table></div>
<?php if(($h['recorded_timezone']??null)===null):?><p class="tx-muted">The original entry did not record the time basis; its stored creation time is shown.</p><?php endif;?></details>
