<details><summary>Evidence accounting details</summary><p><?= ui_escape($j['evidence_coverage']['status']??'Not recorded') ?></p><?php foreach(['debit','credit'] as $side):if(!isset($j['evidence_coverage'][$side]))continue;$coverage=$j['evidence_coverage'][$side];?><p><?= ucfirst($side) ?>: <?= ui_escape($coverage['covered']===null?'Not recorded':accounting_money($coverage['covered'])) ?> supported of <?= ui_escape(accounting_money($coverage['eligible'])) ?></p><?php endforeach;?></details>
</details>
