<?php if($admin&&($j['correction_entry_available']??false)===true&&($j['correction_eligible']??false)===true):?><details class="tx-more-actions"><summary>More actions</summary><nav class="tx-next-actions" aria-label="Transaction correction"><a class="ui-button" href="journal_correction.php?journal_id=<?= $id ?>">Correct this transaction</a><a class="ui-button" href="journal_correction.php?journal_id=<?= $id ?>&amp;mode=reverse_only">Reverse an entry recorded by mistake</a></nav><p class="tx-muted">The next step checks eligibility and linked operations. A reversal is not an actual return of cash.</p><p class="tx-muted">For unused advance cash, use the return workflow on its Cash Advance.</p></details><?php endif;?>
